using System;
using System.Collections.Generic;
using System.Globalization;
using System.IO;
using System.Linq;
using System.Text.RegularExpressions;
using System.Threading.Tasks;
using System.Windows;
using System.Windows.Controls;

namespace RogControl {
 public partial class MainWindow {
  readonly WorkerClient discoveryWorker=new WorkerClient(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"DiscoveryWorker.exe"),20000);
  readonly List<Dictionary<string,object>> discoveredHardware=new List<Dictionary<string,object>>();
  static bool DiscoverySignatureKnown(string pid,string name,bool knownBoard){
   if(pid=="1AA6")return knownBoard&&name.Equals("AURA LED Controller",StringComparison.OrdinalIgnoreCase);
   if(pid=="1C83")return knownBoard&&name.Equals("Motherboard LCD Panel",StringComparison.OrdinalIgnoreCase);
   if(pid=="1D98")return name.Equals("ROG EURUX Controller",StringComparison.OrdinalIgnoreCase);
   if(pid=="1D41")return name.Equals("ROG DELTA II-KJP (2.4GHz)",StringComparison.OrdinalIgnoreCase);
   if(pid=="1ACE")return name.Equals("ROG OMNI RECEIVER",StringComparison.OrdinalIgnoreCase);
   if(pid=="1AD0"||pid=="1D7A"||pid=="1D7C")return new[]{"ROG HARPE II EXTREME EDITION 20","ROG HARPE II EXTREME EDITION20"}.Contains(name,StringComparer.OrdinalIgnoreCase);
   if(pid=="1DA2"||pid=="1DA4"||pid=="1D54")return new[]{"ROG AZOTH EXTREME EDITION 20","ROG AZOTH EXTREME EDITION20"}.Contains(name,StringComparer.OrdinalIgnoreCase);
   return false;
  }
  bool DiscoveryAlreadyRepresented(IDictionary<string,object> item){return DiscoverySignatureKnown(DiscoveryText(item,"pid"),DiscoveryText(item,"name"),String.Equals(info.Board,"ROG CROSSHAIR X870E EXTREME",StringComparison.OrdinalIgnoreCase));}
  static string DiscoveryNameSource(IDictionary<string,object> item){string source=DiscoveryText(item,"nameSource");return source=="busReportedDeviceDesc"?"设备提供的名称":source=="friendlyName"?"Windows 显示名称":source=="deviceDescription"?"Windows 设备描述":"未读取";}
  string discoveryMessage="尚未扫描新设备。",discoveryCapturedAt="";bool discoveryCompleted;
  static string DiscoveryText(IDictionary<string,object> item,string key,string missing=""){object value;if(item==null||!item.TryGetValue(key,out value)||!(value is string))return missing;string result=new string(((string)value).Where(c=>!Char.IsControl(c)).Take(240).ToArray()).Trim();return result.Length==0?missing:result;}
  static bool DiscoveryEntryValid(Dictionary<string,object> item){return item!=null&&OriginalStateFlag(item,"present")==true&&OriginalStateFlag(item,"vendorConfirmed")==true&&OriginalStateFlag(item,"controlSupported")==false&&DiscoveryText(item,"vid")=="0B05"&&Regex.IsMatch(DiscoveryText(item,"deviceId"),"^[0-9a-f]{64}$")&&(DiscoveryText(item,"pid")==""||Regex.IsMatch(DiscoveryText(item,"pid"),"^[0-9A-F]{4}$"))&&(DiscoveryText(item,"transport")=="USB"||DiscoveryText(item,"transport")=="unknown");}
  static string DiscoveryTransport(IDictionary<string,object> item){return DiscoveryText(item,"transport")=="USB"?"USB":"连接方式未确认";}
  static string DiscoveryPid(IDictionary<string,object> item){string pid=DiscoveryText(item,"pid");return pid.Length==0?"PID 未确认":("PID "+pid);}
  // The tools compatibility page owns the scanner; no sidebar or known-product
  // positions are changed. Only exact current product signatures are hidden from this extra list.
  void OriginalDiscoveryGallery(StackPanel target){target.Children.Add(new Border{Height=1,Background=border,Margin=new Thickness(0,12,0,22)});target.Children.Add(Label("新发现设备",18,text));var row=new Grid{Margin=new Thickness(0,12,0,0)};row.ColumnDefinitions.Add(new ColumnDefinition{Width=GridLength.Auto});row.ColumnDefinitions.Add(new ColumnDefinition());var scan=Button(busy?"正在扫描…":"扫描已连接设备",async()=>await ReadOriginalDiscovery());scan.IsEnabled=!busy&&!render&&!closing;row.Children.Add(scan);var state=Paragraph(busy?"":discoveryCompleted?"扫描完成":discoveryMessage,12,muted);state.VerticalAlignment=VerticalAlignment.Center;state.Margin=new Thickness(12,0,0,0);Grid.SetColumn(state,1);row.Children.Add(state);target.Children.Add(row);
   var unknown=discoveredHardware.Where(d=>!DiscoveryAlreadyRepresented(d)).ToList();if(unknown.Count>0){var grid=new Grid{Margin=new Thickness(0,18,0,0)};for(int i=0;i<3;i++)grid.ColumnDefinitions.Add(new ColumnDefinition());for(int i=0;i<(unknown.Count+2)/3;i++)grid.RowDefinitions.Add(new RowDefinition{Height=GridLength.Auto});for(int i=0;i<unknown.Count;i++){var hardware=unknown[i];string id=DiscoveryText(hardware,"deviceId");var card=new StackPanel{Margin=new Thickness(i%3==0?0:14,0,i%3==2?0:14,22)};card.Children.Add(Label(DiscoveryText(hardware,"name","名称未读取"),15,text));card.Children.Add(Paragraph("VID 0B05 · "+DiscoveryPid(hardware)+" · "+DiscoveryTransport(hardware),12,muted));card.Children.Add(Paragraph(OriginalStateFlag(hardware,"physicalIdentityConfirmed")==true?"仅识别 · 尚未适配控制":"身份未确认 · 尚未适配控制",12,accent));card.Children.Add(Button("查看设备信息",()=>ShowPage("device:discovered:"+id)));Grid.SetColumn(card,i%3);Grid.SetRow(card,i/3);grid.Children.Add(card);}target.Children.Add(grid);}else if(discoveryCompleted)target.Children.Add(Paragraph("未发现新增 ASUS 设备。",12,muted));
   if(discoveryCompleted&&discoveredHardware.Count>0){int physical=discoveredHardware.Count(d=>OriginalStateFlag(d,"physicalIdentityConfirmed")==true);var all=new StackPanel();foreach(var hardware in discoveredHardware){string id=DiscoveryText(hardware,"deviceId");var rowHardware=new Grid{Margin=new Thickness(0,10,0,8)};rowHardware.ColumnDefinitions.Add(new ColumnDefinition());rowHardware.ColumnDefinitions.Add(new ColumnDefinition{Width=GridLength.Auto});var description=new StackPanel();description.Children.Add(Label(DiscoveryText(hardware,"name","名称未读取"),13,text));description.Children.Add(Paragraph("VID 0B05 · "+DiscoveryPid(hardware)+" · "+DiscoveryTransport(hardware)+(OriginalStateFlag(hardware,"physicalIdentityConfirmed")==true?"":" · 身份未确认"),11,muted));rowHardware.Children.Add(description);var detail=Button("查看身份信息",()=>ShowPage("device:discovered:"+id));Grid.SetColumn(detail,1);rowHardware.Children.Add(detail);all.Children.Add(rowHardware);}target.Children.Add(new Expander{Header="本次扫描全部硬件（"+physical+"）",Content=all,IsExpanded=false,Foreground=text,Background=Brush("#00000000"),Margin=new Thickness(0,12,0,14)});}
  }
  async Task ReadOriginalDiscovery(){if(busy||closing||render)return;busy=true;status.Text="正在识别已连接 USB/HID 设备…";ShowPage(page);try{var reply=await discoveryWorker.Request<SdkReply>(new Dictionary<string,object>{{"op","scan"}});if(!reply.ok)throw new InvalidOperationException(SdkError(reply.error));if(reply.data==null||OriginalStateFlag(reply.data,"identificationOnly")!=true)throw new InvalidDataException("发现接口未返回只读身份结果。");var raw=GearArray(reply.data,"devices");if(raw==null)throw new InvalidDataException("发现列表缺失。");var found=raw.Select(item=>item as Dictionary<string,object>).ToList();if(found.Count>4096||found.Any(item=>!DiscoveryEntryValid(item)))throw new InvalidDataException("发现结果存在未确认或无效的设备身份。");found=found.GroupBy(item=>DiscoveryText(item,"deviceId"),StringComparer.Ordinal).Select(group=>group.First()).ToList();discoveredHardware.Clear();discoveredHardware.AddRange(found);discoveryCompleted=true;DateTime captured;string at=OriginalStateText(reply.data,"capturedAt","");discoveryCapturedAt=DateTime.TryParse(at,CultureInfo.InvariantCulture,DateTimeStyles.RoundtripKind,out captured)?captured.ToString("MM-dd HH:mm:ss"):"本次扫描";int physical=found.Count(d=>OriginalStateFlag(d,"physicalIdentityConfirmed")==true),unresolved=found.Count-physical,unknown=found.Count(d=>!DiscoveryAlreadyRepresented(d));discoveryMessage=discoveryCapturedAt+" · 识别 "+physical+" 个硬件 · "+unknown+" 项仅识别新入口"+(unresolved>0?" · "+unresolved+" 个功能节点物理身份未确认":"");Log(discoveryMessage);if(page=="设备")status.Text="";}catch(Exception ex){discoveredHardware.Clear();discoveryCompleted=false;discoveryCapturedAt="";discoveryMessage="扫描未完成："+ex.Message;Log(discoveryMessage);}finally{busy=false;if(!closing)ShowPage(page);}}
  // Route device:discovered:<sha256> here. This page contains no apply control,
  // device command, adapter loading, driver download or automatic registration.
  void OriginalDiscoveredDevicePage(string id){var hardware=discoveredHardware.FirstOrDefault(item=>DiscoveryText(item,"deviceId")==id);Header(hardware==null?"新发现设备":DiscoveryText(hardware,"name","名称未读取"),"");var back=Button("返回设备兼容",()=>ShowPage("设备兼容"));content.Children.Add(back);if(hardware==null){content.Children.Add(Paragraph("设备未在当前扫描结果中，请重新扫描。",13,muted));return;}bool represented=DiscoveryAlreadyRepresented(hardware);content.Children.Add(Paragraph(represented?"仅身份信息 · 此页不提供控制":"仅识别 · 尚未适配控制",17,accent));var fields=new[]{new[]{"Windows 名称",DiscoveryText(hardware,"name","未读取")},new[]{"VID / PID","0B05 / "+DiscoveryText(hardware,"pid","未确认")},new[]{"连接方式",DiscoveryTransport(hardware)},new[]{"扫描时状态","存在 · "+discoveryCapturedAt},new[]{"身份分组",DiscoveryText(hardware,"identityScope")=="usbParent"?"USB 物理父设备":DiscoveryText(hardware,"identityScope")=="container"?"Windows 设备容器":"未确认"},new[]{"名称来源",DiscoveryNameSource(hardware)},new[]{"合并的功能节点",OriginalStateText(hardware,"functionCount","—")}};foreach(var field in fields)OriginalDiscoveryIdentityField(field[0],field[1]);var products=GearArray(hardware,"observedProductIds");if(products!=null&&products.Length>1)OriginalDiscoveryIdentityField("PID 列表",String.Join("、",products.Select(p=>Convert.ToString(p))));var scan=Button("重新扫描已连接设备",async()=>await ReadOriginalDiscovery());scan.IsEnabled=!busy&&!render&&!closing;content.Children.Add(scan);}
  void OriginalDiscoveryIdentityField(string name,string value){var row=new Grid{Margin=new Thickness(0,12,0,0)};row.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(170)});row.ColumnDefinitions.Add(new ColumnDefinition());row.Children.Add(Label(name,13,muted));var detail=Paragraph(value,13,text);Grid.SetColumn(detail,1);row.Children.Add(detail);content.Children.Add(row);}
  public void DisposeOriginalDiscovery(){discoveryWorker.Dispose();}
 }
}
